INSERT INTO `teaching_programs` (`id`, `user_id`, `subject_id`, `class_id`, `type`, `grade_level`, `pekan_efektif`, `atp_items`, `prota`, `promes`, `jp_per_week`, `total_effective_weeks`, `total_effective_hours`, `week`, `month`, `topic`, `subtopic`, `status`, `semester`, `academic_year`, `notes`, `created_at`, `updated_at`) VALUES ('1', '362', NULL, NULL, 'calendar_structure', '7', '[{\"name\":\"Januari\",\"totalWeeks\":4,\"nonEffectiveWeeks\":\"3\",\"keterangan\":null,\"isAuto\":true},{\"name\":\"Februari\",\"totalWeeks\":4,\"nonEffectiveWeeks\":1,\"keterangan\":\"Libur Awal Puasa Ramadan 1447 H\",\"isAuto\":true},{\"name\":\"Maret\",\"totalWeeks\":4,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"April\",\"totalWeeks\":5,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"Mei\",\"totalWeeks\":4,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"Juni\",\"totalWeeks\":4,\"nonEffectiveWeeks\":1,\"keterangan\":\"Libur Kenaikan Kelas (Akhir Tahun Ajaran)\",\"isAuto\":true}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', 'Genap', '2025/2026', NULL, '2026-04-24 22:22:23', '2026-05-16 12:44:09');
INSERT INTO `teaching_programs` (`id`, `user_id`, `subject_id`, `class_id`, `type`, `grade_level`, `pekan_efektif`, `atp_items`, `prota`, `promes`, `jp_per_week`, `total_effective_weeks`, `total_effective_hours`, `week`, `month`, `topic`, `subtopic`, `status`, `semester`, `academic_year`, `notes`, `created_at`, `updated_at`) VALUES ('2', '362', '5', NULL, 'subject_program', '7', '[{\"name\":\"Januari\",\"totalWeeks\":4,\"nonEffectiveWeeks\":\"3\",\"keterangan\":null,\"isAuto\":true},{\"name\":\"Februari\",\"totalWeeks\":4,\"nonEffectiveWeeks\":1,\"keterangan\":\"Libur Awal Puasa Ramadan 1447 H\",\"isAuto\":true},{\"name\":\"Maret\",\"totalWeeks\":4,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"April\",\"totalWeeks\":5,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"Mei\",\"totalWeeks\":4,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"Juni\",\"totalWeeks\":4,\"nonEffectiveWeeks\":1,\"keterangan\":\"Libur Kenaikan Kelas (Akhir Tahun Ajaran)\",\"isAuto\":true}]', NULL, '[{\"id\":1,\"elemen\":\"Analisis Data\",\"materi\":\"Pengenalan Perkakas Analisis Data Lembar Kerja\",\"kd\":\"Peserta didik mampu mengoperasikan antarmuka perangkat lunak lembar kerja untuk mengolah data sederhana secara mandiri.\",\"jp\":3,\"profilLulusan\":\"Kemandirian\"},{\"id\":2,\"elemen\":\"Analisis Data\",\"materi\":\"Input dan Validasi Data Tabel\",\"kd\":\"Peserta didik mampu memasukkan data ke dalam tabel dan melakukan validasi input untuk memastikan akurasi data.\",\"jp\":6,\"profilLulusan\":\"Penalaran Kritis\"},{\"id\":3,\"elemen\":\"Analisis Data\",\"materi\":\"Pengolahan Data dengan Fungsi Dasar\",\"kd\":\"Peserta didik mampu menerapkan rumus fungsi dasar seperti SUM, AVERAGE, dan COUNT untuk menganalisis kumpulan data.\",\"jp\":6,\"profilLulusan\":\"Penalaran Kritis\"},{\"id\":4,\"elemen\":\"Analisis Data\",\"materi\":\"Visualisasi Data dalam Grafik\",\"kd\":\"Peserta didik mampu menyajikan hasil olahan data ke dalam bentuk grafik yang komunikatif dan informatif.\",\"jp\":6,\"profilLulusan\":\"Komunikasi\"},{\"id\":5,\"elemen\":\"Algoritma dan Pemrograman\",\"materi\":\"Konsep Dasar Pemrograman Visual Scratch\",\"kd\":\"Peserta didik mampu memahami alur logika pemrograman menggunakan blok visual Scratch untuk membuat urutan instruksi.\",\"jp\":3,\"profilLulusan\":\"Penalaran Kritis\"},{\"id\":6,\"elemen\":\"Algoritma dan Pemrograman\",\"materi\":\"Implementasi Kontrol Perulangan dan Percabangan\",\"kd\":\"Peserta didik mampu menyusun algoritma yang melibatkan struktur kontrol perulangan dan percabangan dalam Scratch.\",\"jp\":6,\"profilLulusan\":\"Kreativitas\"},{\"id\":7,\"elemen\":\"Algoritma dan Pemrograman\",\"materi\":\"Pengembangan Proyek Interaktif Scratch\",\"kd\":\"Peserta didik mampu mengembangkan proyek interaktif berbasis visual yang menerapkan logika pemrograman kompleks.\",\"jp\":6,\"profilLulusan\":\"Kreativitas\"},{\"id\":8,\"elemen\":\"Dampak Sosial Informatika\",\"materi\":\"Identifikasi Informasi Palsu di Media Digital\",\"kd\":\"Peserta didik mampu menganalisis ciri-ciri informasi palsu untuk meningkatkan literasi digital dan keamanan informasi.\",\"jp\":3,\"profilLulusan\":\"Keimanan & Ketakwaan\"},{\"id\":9,\"elemen\":\"Dampak Sosial Informatika\",\"materi\":\"Edukasi Kewargaan Digital dan Etika Online\",\"kd\":\"Peserta didik mampu menerapkan etika berkomunikasi dan berinteraksi yang bertanggung jawab dalam ekosistem digital.\",\"jp\":3,\"profilLulusan\":\"Kewargaan\"},{\"id\":10,\"elemen\":\"Praktik Lintas Bidang\",\"materi\":\"Perencanaan Proyek Informatika Terintegrasi\",\"kd\":\"Peserta didik mampu berkolaborasi dalam tim untuk merancang solusi masalah nyata menggunakan perangkat informatika.\",\"jp\":6,\"profilLulusan\":\"Kolaborasi\"},{\"id\":11,\"elemen\":\"Praktik Lintas Bidang\",\"materi\":\"Evaluasi dan Pelaporan Akhir Proyek\",\"kd\":\"Peserta didik mampu merefleksikan hasil proyek informatika dan mengomunikasikan temuan secara sistematis.\",\"jp\":9,\"profilLulusan\":\"Komunikasi\"}]', '{\"1_0_0\":\"3\",\"2_1_0\":\"3\",\"2_1_1\":\"3\",\"3_1_2\":\"3\",\"3_2_0\":\"3\",\"4_2_1\":\"3\",\"4_2_2\":\"3\",\"5_2_3\":\"3\",\"6_3_0\":\"3\",\"6_3_1\":\"3\",\"7_3_2\":\"3\",\"7_3_3\":\"3\",\"8_3_4\":\"3\",\"9_4_0\":\"3\",\"10_4_1\":\"3\",\"10_4_2\":\"3\",\"11_4_3\":\"3\",\"11_5_0\":\"3\",\"11_5_1\":\"3\"}', '3', '20', '60', NULL, NULL, NULL, NULL, 'pending', 'Genap', '2025/2026', NULL, '2026-04-24 22:22:23', '2026-05-16 12:45:37');
INSERT INTO `teaching_programs` (`id`, `user_id`, `subject_id`, `class_id`, `type`, `grade_level`, `pekan_efektif`, `atp_items`, `prota`, `promes`, `jp_per_week`, `total_effective_weeks`, `total_effective_hours`, `week`, `month`, `topic`, `subtopic`, `status`, `semester`, `academic_year`, `notes`, `created_at`, `updated_at`) VALUES ('3', '362', '5', NULL, 'atp_document', '7', NULL, '[{\"no\":1,\"elemen\":\"Analisis Data\",\"materi\":\"Analisis Data (Perkakas, Pengolahan): Pengenalan Perkakas Pengolah Angka\",\"tp\":\"Peserta didik mampu mengidentifikasi fungsi dasar perangkat lunak pengolah angka untuk mengolah data secara efisien sebagai fondasi literasi sains data.\",\"jp\":3,\"profilLulusan\":\"Penalaran Kritis\"},{\"no\":2,\"elemen\":\"Analisis Data\",\"materi\":\"Analisis Data (Perkakas, Pengolahan): Penginputan dan Format Data\",\"tp\":\"Peserta didik mampu melakukan input data dan menerapkan format sel untuk menyajikan informasi yang akurat dan rapi.\",\"jp\":6,\"profilLulusan\":\"Kemandirian\"},{\"no\":3,\"elemen\":\"Analisis Data\",\"materi\":\"Analisis Data (Perkakas, Pengolahan): Fungsi Statistik Dasar\",\"tp\":\"Peserta didik mampu menggunakan rumus statistik dasar (SUM, AVERAGE, MIN, MAX) untuk menarik kesimpulan matematis dari kumpulan data.\",\"jp\":6,\"profilLulusan\":\"Penalaran Kritis\"},{\"no\":4,\"elemen\":\"Algoritma dan Pemrograman\",\"materi\":\"Algoritma dan Pemrograman (Visual Scratch): Pengenalan Lingkungan Visual Scratch\",\"tp\":\"Peserta didik mampu mengeksplorasi antarmuka dan blok perintah pada lingkungan pemrograman visual Scratch.\",\"jp\":3,\"profilLulusan\":\"Kreativitas\"},{\"no\":5,\"elemen\":\"Algoritma dan Pemrograman\",\"materi\":\"Algoritma dan Pemrograman (Visual Scratch): Logika Urutan dan Perulangan\",\"tp\":\"Peserta didik mampu menyusun algoritma sederhana menggunakan blok urutan dan perulangan untuk menggerakkan objek.\",\"jp\":6,\"profilLulusan\":\"Penalaran Kritis\"},{\"no\":6,\"elemen\":\"Algoritma dan Pemrograman\",\"materi\":\"Algoritma dan Pemrograman (Visual Scratch): Pengkondisian dan Variabel\",\"tp\":\"Peserta didik mampu menerapkan logika pengkondisian (if-then) dan variabel untuk membuat interaksi program yang dinamis.\",\"jp\":9,\"profilLulusan\":\"Kreativitas\"},{\"no\":7,\"elemen\":\"Dampak Sosial Informatika\",\"materi\":\"Dampak Sosial Informatika (Informasi Palsu): Identifikasi Informasi Palsu\",\"tp\":\"Peserta didik mampu menganalisis ciri-ciri informasi palsu (hoaks) dan memahami dampaknya terhadap kehidupan bermasyarakat.\",\"jp\":6,\"profilLulusan\":\"Kewargaan\"},{\"no\":8,\"elemen\":\"Dampak Sosial Informatika\",\"materi\":\"Dampak Sosial Informatika (Informasi Palsu): Etika Penyebaran Informasi\",\"tp\":\"Peserta didik mampu menunjukkan sikap tanggung jawab moral dalam menyebarkan informasi sebagai perwujudan etika digital.\",\"jp\":6,\"profilLulusan\":\"Keimanan & Ketakwaan\"},{\"no\":9,\"elemen\":\"Praktika Lintas Bidang\",\"materi\":\"Praktika Lintas Bidang (Proyek): Perencanaan Proyek Informatika\",\"tp\":\"Peserta didik mampu berkolaborasi dalam kelompok untuk merencanakan proyek integratif yang menggabungkan analisis data dan pemrograman.\",\"jp\":6,\"profilLulusan\":\"Kolaborasi\"},{\"no\":10,\"elemen\":\"Praktika Lintas Bidang\",\"materi\":\"Praktika Lintas Bidang (Proyek): Implementasi dan Komunikasi Proyek\",\"tp\":\"Peserta didik mampu mengimplementasikan solusi proyek dan mengomunikasikan hasil karya secara efektif kepada audiens.\",\"jp\":9,\"profilLulusan\":\"Komunikasi\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', 'Genap', '2025/2026', NULL, '2026-04-24 22:23:57', '2026-05-16 12:44:47');
