n Teks Cerita Pengalaman Pribadi Berbasis Digital\",\"kd\":\"Siswa mampu nyunting teks cerita pribadi ngguna\'aghi piranti digital kalaban nerap\'aghi etika kewargaan digital.\",\"jp\":4,\"profilLulusan\":\"Literasi AI & Sains Data\"},{\"id\":5,\"elemen\":\"Berbicara dan Mempresentasikan\",\"materi\":\"Analisis Unsur Teks Berita (Pawarta Lokal)\",\"kd\":\"Siswa mampu nyebhut\'aghi unsur-unsur Pawarta Lokal (5W+1H) d\\u00e2ri media cetak otab\\u00e2 elektronik kalaban kritis.\",\"jp\":4,\"profilLulusan\":\"Penalaran Kritis\"},{\"id\":6,\"elemen\":\"Berbicara dan Mempresentasikan\",\"materi\":\"Praktik Menjadi Reporter Pawarta Lokal\",\"kd\":\"Siswa mampu meragakan cara maca pawarta lokal kalaban teknik vokal se bhender b\\u00e2n penuh tanggung jawab moral.\",\"jp\":4,\"profilLulusan\":\"Keimanan & Ketakwaan\"},{\"id\":7,\"elemen\":\"Menulis\",\"materi\":\"Penulisan Berita Pawarta Lokal Berbasis Data\",\"kd\":\"Siswa mampu nulis teks pawarta lokal d\\u00e2ri kabh\\u00e2dhi\'an sakitar sekolah kalaban akurasi data se akurat.\",\"jp\":4,\"profilLulusan\":\"Analisis Data Modern\"},{\"id\":8,\"elemen\":\"Menulis\",\"materi\":\"Kolaborasi Publikasi Berita Lokal\",\"kd\":\"Siswa mampu makarya sareng (kolaborasi) d\\u00e2lem nyoson buletin kelas se eisi pawarta lokal.\",\"jp\":4,\"profilLulusan\":\"Kolaborasi\"},{\"id\":9,\"elemen\":\"Berbicara dan Mempresentasikan\",\"materi\":\"Eksplorasi Aksara Dasar Madura\",\"kd\":\"Siswa mampu ngaos aksara dasar Madura kalaban lancar b\\u00e2n ngenal sajarah aksara daerah.\",\"jp\":4,\"profilLulusan\":\"Kemandirian\"},{\"id\":10,\"elemen\":\"Menulis\",\"materi\":\"Penerapan Sandhangan Aksara Madura\",\"kd\":\"Siswa mampu nulis tembung ngguna\'aghi aksara dasar b\\u00e2n sandhangan kalaban bhender b\\u00e2n disiplin.\",\"jp\":4,\"profilLulusan\":\"Kemandirian\"},{\"id\":11,\"elemen\":\"Menulis\",\"materi\":\"Proyek Literasi Aksara Daerah Digital\",\"kd\":\"Siswa mampu nulis kal\\u00e8mat sederhana ngguna\'aghi aksara Madura d\\u00e2lem aplikasi digital kalaban kreatif.\",\"jp\":6,\"profilLulusan\":\"Kreativitas\"}]', '{\"1_0_0\":\"2\",\"1_0_1\":\"2\",\"2_0_2\":\"2\",\"2_0_3\":\"2\",\"3_1_0\":\"2\",\"3_1_1\":\"2\",\"4_1_2\":\"2\",\"4_2_0\":\"2\",\"5_2_1\":\"2\",\"5_2_2\":\"2\",\"6_2_3\":\"2\",\"6_3_0\":\"2\",\"7_3_1\":\"2\",\"7_3_2\":\"2\",\"8_3_3\":\"2\",\"8_3_4\":\"2\",\"9_4_0\":\"2\",\"9_4_1\":\"2\",\"10_4_2\":\"2\",\"10_4_3\":\"2\",\"11_5_0\":\"2\",\"11_5_1\":\"2\",\"11_5_2\":\"2\"}', '2', '23', '46', NULL, NULL, NULL, NULL, 'pending', 'Genap', '2025/2026', NULL, '2026-05-16 08:07:26', '2026-05-16 08:11:29');
