INSERT INTO `teaching_programs` (`id`, `user_id`, `subject_id`, `class_id`, `type`, `grade_level`, `pekan_efektif`, `atp_items`, `prota`, `promes`, `jp_per_week`, `total_effective_weeks`, `total_effective_hours`, `week`, `month`, `topic`, `subtopic`, `status`, `semester`, `academic_year`, `notes`, `created_at`, `updated_at`) VALUES ('11', '358', '4', NULL, 'subject_program', '7', '[{\"name\":\"Januari\",\"totalWeeks\":4,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"Februari\",\"totalWeeks\":4,\"nonEffectiveWeeks\":1,\"keterangan\":\"Libur Awal Puasa Ramadan 1447 H\",\"isAuto\":true},{\"name\":\"Maret\",\"totalWeeks\":4,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"April\",\"totalWeeks\":5,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"Mei\",\"totalWeeks\":4,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"Juni\",\"totalWeeks\":4,\"nonEffectiveWeeks\":1,\"keterangan\":\"Libur Kenaikan Kelas (Akhir Tahun Ajaran)\",\"isAuto\":true}]', NULL, '[{\"id\":1,\"elemen\":\"Pemahaman Konsep\",\"materi\":\"Analisis Potensi Sumber Daya Alam dan Ekonomi Lingkungan\",\"kd\":\"Pada akhir Fase D, peserta didik mampu mengidentifikasi potensi ekonomi lingkungan melalui analisis data sumber daya alam di daerah sekitar dengan penalaran kritis.\",\"jp\":8,\"profilLulusan\":\"Penalaran Kritis\"},{\"id\":2,\"elemen\":\"Pemahaman Konsep\",\"materi\":\"Mekanisme Pasar dan Peran Ekonomi dalam Ekosistem\",\"kd\":\"Pada akhir Fase D, peserta didik mampu menjelaskan keterkaitan antara potensi ekonomi lingkungan dengan mekanisme pasar dalam mendukung keberlangsungan hidup masyarakat.\",\"jp\":8,\"profilLulusan\":\"Kewargaan\"},{\"id\":3,\"elemen\":\"Pemahaman Konsep\",\"materi\":\"Dampak Eksploitasi Lingkungan terhadap Ekonomi\",\"kd\":\"Pada akhir Fase D, peserta didik mampu mengevaluasi dampak negatif eksploitasi lingkungan berlebih terhadap stabilitas ekonomi lokal dengan pendekatan etika moral.\",\"jp\":8,\"profilLulusan\":\"Keimanan & Ketakwaan\"},{\"id\":4,\"elemen\":\"Pemahaman Konsep\",\"materi\":\"Penerapan Prinsip Ekonomi Berkelanjutan\",\"kd\":\"Pada akhir Fase D, peserta didik mampu merancang strategi pemanfaatan potensi ekonomi lingkungan yang berkelanjutan dengan prinsip efisiensi.\",\"jp\":8,\"profilLulusan\":\"Kreativitas\"},{\"id\":5,\"elemen\":\"Keterampilan Proses\",\"materi\":\"Observasi Lapangan Potensi Ekonomi Lingkungan\",\"kd\":\"Pada akhir Fase D, peserta didik mampu melakukan observasi data lapangan terkait potensi ekonomi lingkungan menggunakan perangkat digital secara akurat.\",\"jp\":12,\"profilLulusan\":\"Literasi AI & Sains Data\"},{\"id\":6,\"elemen\":\"Keterampilan Proses\",\"materi\":\"Interpretasi Data Ekonomi Lingkungan\",\"kd\":\"Pada akhir Fase D, peserta didik mampu mengolah data hasil observasi menjadi informasi yang bermakna bagi pemetaan ekonomi wilayah.\",\"jp\":8,\"profilLulusan\":\"Analisis Data Modern\"},{\"id\":7,\"elemen\":\"Pemahaman Konsep\",\"materi\":\"Konsep Dasar Pemberdayaan Masyarakat\",\"kd\":\"Pada akhir Fase D, peserta didik mampu mendefinisikan konsep pemberdayaan masyarakat sebagai upaya peningkatan kapasitas ekonomi dan sosial.\",\"jp\":8,\"profilLulusan\":\"Kewargaan\"},{\"id\":8,\"elemen\":\"Pemahaman Konsep\",\"materi\":\"Strategi Inklusi Sosial dalam Pemberdayaan\",\"kd\":\"Pada akhir Fase D, peserta didik mampu merumuskan langkah-langkah pemberdayaan masyarakat yang inklusif untuk mengurangi kesenjangan ekonomi.\",\"jp\":8,\"profilLulusan\":\"Kolaborasi\"},{\"id\":9,\"elemen\":\"Keterampilan Proses\",\"materi\":\"Perancangan Program Pemberdayaan Berbasis Komunitas\",\"kd\":\"Pada akhir Fase D, peserta didik mampu menyusun proposal ide program pemberdayaan masyarakat secara mandiri dengan mempertimbangkan kearifan lokal.\",\"jp\":12,\"profilLulusan\":\"Kemandirian\"},{\"id\":10,\"elemen\":\"Keterampilan Proses\",\"materi\":\"Komunikasi Hasil Analisis dan Program Pemberdayaan\",\"kd\":\"Pada akhir Fase D, peserta didik mampu mengomunikasikan hasil analisis potensi ekonomi dan rencana pemberdayaan masyarakat melalui media digital yang aman dan etis.\",\"jp\":12,\"profilLulusan\":\"Komunikasi, Kewargaan Digital\"}]', '{\"1_0_0\":\"4\",\"1_0_1\":\"4\",\"2_0_2\":\"4\",\"2_0_3\":\"4\",\"3_1_0\":\"4\",\"3_1_1\":\"4\",\"4_1_2\":\"4\",\"4_2_0\":\"4\",\"5_2_1\":\"4\",\"5_2_2\":\"4\",\"5_2_3\":\"4\",\"6_3_0\":\"4\",\"6_3_1\":\"4\",\"7_3_2\":\"4\",\"7_3_3\":\"4\",\"8_3_4\":\"4\",\"8_4_0\":\"4\",\"9_4_1\":\"4\",\"9_4_2\":\"4\",\"9_4_3\":\"4\",\"10_5_0\":\"4\",\"10_5_1\":\"4\",\"10_5_2\":\"4\"}', '4', '23', '92', NULL, NULL, NULL, NULL, 'pending', 'Genap', '2025/2026', NULL, '2026-05-16 12:58:22', '2026-05-16 13:03:59');
INSERT INTO `teaching_programs` (`id`, `user_id`, `subject_id`, `class_id`, `type`, `grade_level`, `pekan_efektif`, `atp_items`, `prota`, `promes`, `jp_per_week`, `total_effective_weeks`, `total_effective_hours`, `week`, `month`, `topic`, `subtopic`, `status`, `semester`, `academic_year`, `notes`, `created_at`, `updated_at`) VALUES ('12', '361', '13', NULL, 'subject_program', '7', '[{\"name\":\"Januari\",\"totalWeeks\":4,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"Februari\",\"totalWeeks\":4,\"nonEffectiveWeeks\":1,\"keterangan\":\"Libur Awal Puasa Ramadan 1447 H\",\"isAuto\":true},{\"name\":\"Maret\",\"totalWeeks\":4,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"April\",\"totalWeeks\":5,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"Mei\",\"totalWeeks\":4,\"nonEffectiveWeeks\":0,\"keterangan\":null,\"isAuto\":true},{\"name\":\"Juni\",\"totalWeeks\":4,\"nonEffectiveWeeks\":1,\"keterangan\":\"Libur Kenaikan Kelas (Akhir Tahun Ajaran)\",\"isAuto\":true}]', NULL, '[{\"id\":1,\"elemen\":\"Produksi\",\"materi\":\"Prinsip Dasar Alat Penjernih Air\",\"kd\":\"Pada akhir Fase D, peserta didik mampu menganalisis karakteristik bahan alami dan buatan untuk rekayasa produk penjernih air dengan penalaran kritis.\",\"jp\":6,\"profilLulusan\":\"Penalaran Kritis\"},{\"id\":2,\"elemen\":\"Produksi\",\"materi\":\"Desain Teknis Alat Penjernih Air\",\"kd\":\"Pada akhir Fase D, peserta didik mampu merancang sketsa alat penjernih air yang inovatif dengan mengintegrasikan prinsip efisiensi dan kreativitas.\",\"jp\":6,\"profilLulusan\":\"Kreativitas\"},{\"id\":3,\"elemen\":\"Produksi\",\"materi\":\"Konstruksi dan Perakitan Alat Penjernih Air\",\"kd\":\"Pada akhir Fase D, peserta didik mampu mendemonstrasikan keterampilan teknis dalam merakit alat penjernih air secara mandiri dan sistematis.\",\"jp\":6,\"profilLulusan\":\"Kemandirian\"},{\"id\":4,\"elemen\":\"Refleksi dan Evaluasi\",\"materi\":\"Uji Kinerja Alat Penjernih Air\",\"kd\":\"Pada akhir Fase D, peserta didik mampu mengevaluasi efektivitas hasil rakitan alat penjernih air berdasarkan parameter kualitas air yang dihasilkan.\",\"jp\":6,\"profilLulusan\":\"Penalaran Kritis\"},{\"id\":5,\"elemen\":\"Produksi\",\"materi\":\"Teknik Budi Daya Tanaman Sayuran\",\"kd\":\"Pada akhir Fase D, peserta didik mampu mengidentifikasi kebutuhan teknis budi daya tanaman sayuran sesuai dengan kondisi lingkungan lokal.\",\"jp\":6,\"profilLulusan\":\"Kesehatan\"},{\"id\":6,\"elemen\":\"Produksi\",\"materi\":\"Manajemen Perawatan Tanaman Sayuran\",\"kd\":\"Pada akhir Fase D, peserta didik mampu melaksanakan prosedur pemeliharaan tanaman sayuran secara kolaboratif dengan tanggung jawab lingkungan.\",\"jp\":6,\"profilLulusan\":\"Kolaborasi\"},{\"id\":7,\"elemen\":\"Refleksi dan Evaluasi\",\"materi\":\"Analisis Pertumbuhan dan Hasil Panen\",\"kd\":\"Pada akhir Fase D, peserta didik mampu melakukan refleksi atas proses budi daya dan menyajikan laporan hasil panen secara akurat.\",\"jp\":6,\"profilLulusan\":\"Komunikasi\"},{\"id\":8,\"elemen\":\"Produksi\",\"materi\":\"Strategi Pemasaran Produk Sederhana\",\"kd\":\"Pada akhir Fase D, peserta didik mampu menyusun rencana pemasaran sederhana untuk produk hasil karya dengan memanfaatkan etika kewargaan digital.\",\"jp\":9,\"profilLulusan\":\"Kewargaan\"},{\"id\":9,\"elemen\":\"Produksi\",\"materi\":\"Implementasi Pemasaran Digital\",\"kd\":\"Pada akhir Fase D, peserta didik mampu mempromosikan produk secara efektif menggunakan media digital dengan memperhatikan literasi AI dan etika komunikasi.\",\"jp\":9,\"profilLulusan\":\"Komunikasi\"},{\"id\":10,\"elemen\":\"Refleksi dan Evaluasi\",\"materi\":\"Evaluasi Ekonomi dan Dampak Sosial\",\"kd\":\"Pada akhir Fase D, peserta didik mampu mengevaluasi keberhasilan pemasaran produk berdasarkan data penjualan dan nilai kebermanfaatan bagi masyarakat.\",\"jp\":9,\"profilLulusan\":\"Keimanan & Ketakwaan\"}]', NULL, '3', '23', '69', NULL, NULL, NULL, NULL, 'pending', 'Genap', '2025/2026', NULL, '2026-05-16 12:58:23', '2026-05-16 13:03:05');
