ns Data\"},{\"no\":6,\"elemen\":\"Keterampilan Proses\",\"materi\":\"Interpretasi Data Ekonomi Lingkungan\",\"tp\":\"Pada akhir Fase D, peserta didik mampu mengolah data hasil observasi menjadi informasi yang bermakna bagi pemetaan ekonomi wilayah.\",\"jp\":8,\"profilLulusan\":\"Analisis Data Modern\"},{\"no\":7,\"elemen\":\"Pemahaman Konsep\",\"materi\":\"Konsep Dasar Pemberdayaan Masyarakat\",\"tp\":\"Pada akhir Fase D, peserta didik mampu mendefinisikan konsep pemberdayaan masyarakat sebagai upaya peningkatan kapasitas ekonomi dan sosial.\",\"jp\":8,\"profilLulusan\":\"Kewargaan\"},{\"no\":8,\"elemen\":\"Pemahaman Konsep\",\"materi\":\"Strategi Inklusi Sosial dalam Pemberdayaan\",\"tp\":\"Pada akhir Fase D, peserta didik mampu merumuskan langkah-langkah pemberdayaan masyarakat yang inklusif untuk mengurangi kesenjangan ekonomi.\",\"jp\":8,\"profilLulusan\":\"Kolaborasi\"},{\"no\":9,\"elemen\":\"Keterampilan Proses\",\"materi\":\"Perancangan Program Pemberdayaan Berbasis Komunitas\",\"tp\":\"Pada akhir Fase D, peserta didik mampu menyusun proposal ide program pemberdayaan masyarakat secara mandiri dengan mempertimbangkan kearifan lokal.\",\"jp\":12,\"profilLulusan\":\"Kemandirian\"},{\"no\":10,\"elemen\":\"Keterampilan Proses\",\"materi\":\"Komunikasi Hasil Analisis dan Program Pemberdayaan\",\"tp\":\"Pada akhir Fase D, peserta didik mampu mengomunikasikan hasil analisis potensi ekonomi dan rencana pemberdayaan masyarakat melalui media digital yang aman dan etis.\",\"jp\":12,\"profilLulusan\":\"Komunikasi, Kewargaan Digital\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', 'Genap', '2025/2026', NULL, '2026-05-16 13:03:17', '2026-05-16 13:03:17');
INSERT INTO `teaching_programs` (`id`, `user_id`, `subject_id`, `class_id`, `type`, `grade_level`, `pekan_efektif`, `atp_items`, `prota`, `promes`, `jp_per_week`, `total_effective_weeks`, `total_effective_hours`, `week`, `month`, `topic`, `subtopic`, `status`, `semester`, `academic_year`, `notes`, `created_at`, `updated_at`) VALUES ('15', '363', '10', NULL, 'atp_document', '8', NULL, '[{\"no\":1,\"elemen\":\"Membaca Karya Fiksi\",\"materi\":\"Analisis Unsur Intrinsik dalam Karya Fiksi\",\"tp\":\"Peserta didik mampu menganalisis keterkaitan unsur intrinsik dalam karya fiksi melalui pendekatan literasi kritis untuk memahami pesan moral.\",\"jp\":12,\"profilLulusan\":\"Penalaran Kritis\"},{\"no\":2,\"elemen\":\"Membaca Karya Fiksi\",\"materi\":\"Evaluasi Struktur dan Alur Cerita Fiksi\",\"tp\":\"Peserta didik mampu mengevaluasi struktur alur cerita fiksi dengan membandingkan berbagai perspektif naratif secara mandiri.\",\"jp\":12,\"profilLulusan\":\"Kemandirian\"},{\"no\":3,\"elemen\":\"Berbicara dan Mempresentasikan\",\"materi\":\"Teknik Mengulas Karya Fiksi secara Lisan\",\"tp\":\"Peserta didik mampu menyajikan ulasan karya fiksi dengan artikulasi yang tepat dan argumen yang didukung data tekstual.\",\"jp\":12,\"profilLulusan\":\"Komunikasi\"},{\"no\":4,\"elemen\":\"Berbicara dan Mempresentasikan\",\"materi\":\"Diskusi Panel Resensi Karya Fiksi\",\"tp\":\"Peserta didik mampu berkolaborasi dalam diskusi panel untuk mendebat kualitas karya fiksi dengan etika komunikasi digital yang santun.\",\"jp\":12,\"profilLulusan\":\"Kolaborasi\"},{\"no\":5,\"elemen\":\"Menulis\",\"materi\":\"Penyusunan Kerangka Teks Ulasan Fiksi\",\"tp\":\"Peserta didik mampu menyusun kerangka teks ulasan fiksi yang sistematis dengan memanfaatkan literasi AI untuk riset kata kunci.\",\"jp\":12,\"profilLulusan\":\"Literasi AI & Sains Data\"},{\"no\":6,\"elemen\":\"Menulis\",\"materi\":\"Produksi Teks Ulasan Fiksi yang Komprehensif\",\"tp\":\"Peserta didik mampu menulis teks ulasan fiksi yang objektif dengan memperhatikan kaidah kebahasaan dan struktur yang baku.\",\"jp\":12,\"profilLulusan\":\"Penalaran Kritis\"},{\"no\":7,\"elemen\":\"Menulis\",\"materi\":\"Analisis Data untuk Substansi Pidato\",\"tp\":\"Peserta didik mampu melakukan analisis data modern untuk menentukan isu strategis sebagai landasan penulisan teks pidato.\",\"jp\":12,\"profilLulusan\":\"Analisis Data Modern\"},{\"no\":8,\"elemen\":\"Menulis\",\"materi\":\"Konstruksi Argumen dalam Teks Pidato\",\"tp\":\"Peserta didik mampu menulis naskah pidato yang persuasif dengan mengintegrasikan nilai-nilai integritas dan tanggung jawab sosial.\",\"jp\":12,\"profilLulusan\":\"Keimanan & Ketakwaan\"},{\"no\":9,\"elemen\":\"Menulis\",\"materi\":\"Penyuntingan dan Publikasi Digital Teks Pidato\",\"tp\":\"Peserta didik mampu menyunting teks pidato secara kreatif dan mempublikasikannya dengan memperhatikan etika kewargaan digital.\",\"jp\":12,\"profilLulusan\":\"Kewargaan Digital\"},{\"no\":10,\"elemen\":\"Berbicara dan Mempresentasikan\",\"materi\":\"Simulasi Orasi dan Retorika Pidato\",\"tp\":\"Peserta didik mampu melakukan simulasi orasi pidato dengan teknik retorika yang efektif dan gestur yang profesional.\",\"jp\":12,\"profilLulusan\":\"Komunikasi\"},{\"no\":11,\"elemen\":\"Berbicara dan Mempresentasikan\",\"materi\":\"Evaluasi Kinerja Pidato Berbasis Umpan Balik\",\"tp\":\"Peserta didik mampu melakukan evaluasi diri dan rekan sejawat terhadap penampilan pidato berdasarkan kriteria keberhasilan yang disepakati.\",\"jp\":18,\"profilLulusan\":\"Kemandirian\"}]', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'pending', 'Genap', '2025/2026', NULL, '2026-05-16 13:03:25', '2026-05-16 13:03:25');
