  `status` varchar(255) NOT NULL DEFAULT 'Terlaksana',
  `follow_up` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `is_exam` tinyint(1) NOT NULL DEFAULT 0,
  `is_assignment` tinyint(1) NOT NULL DEFAULT 0,
  `user_id` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `journals_schedule_id_foreign` (`schedule_id`),
  KEY `journals_subject_id_foreign` (`subject_id`),
  KEY `journals_user_id_foreign` (`user_id`),
  KEY `idx_journal_monitoring` (`class_id`,`subject_id`,`date`),
  KEY `journals_deleted_at_index` (`deleted_at`),
  CONSTRAINT `journals_class_id_foreign` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `journals_schedule_id_foreign` FOREIGN KEY (`schedule_id`) REFERENCES `schedules` (`id`) ON DELETE CASCADE,
  CONSTRAINT `journals_subject_id_foreign` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `journals_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: grades
DROP TABLE IF EXISTS `grades`;
CREATE TABLE `grades` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
